/bin/bash -lc "python - <<'PY'
from sim import Sim
import itertools, numpy as np

best=[]
home=Sim().home_ctrl()
for torso in [-0.3,-0.15,0,0.15,0.3]:
  for hip in [-0.8,-0.6,-0.4,-0.2,0.0]:
    for knee in [0.7,0.9,1.1,1.3]:
      for ankle in [-0.8,-0.6,-0.4,-0.2,0.0]:
        for sp in [0,0.6,1.0,1.3]:
          for sr in [0,0.3,0.6]:
            for el in [0,0.8,1.4]:
              sim=Sim(); ctrl=home.copy()
              ctrl[2]=ctrl[7]=hip; ctrl[3]=ctrl[8]=knee; ctrl[4]=ctrl[9]=ankle; ctrl[10]=torso
              ctrl[11:15]=[sp,sr,-0.1,el]; ctrl[15:19]=[sp,-sr,0.1,el]
              for _ in range(300):
                sim.data.ctrl[:]=ctrl; sim.step(1)
              p=sim.pelvis_position(); b=sim.box_position(); tu=sim.torso_up(); d=sim.box_distance_to_pelvis()
              stable=(p[2]>=0.74 and tu>=0.50 and b[2]>=0.72 and d<=0.42)
              score=(2 if stable else 0)+p[0]-abs(p[1])*0.3-(np.linalg.norm(b[:2]-[0.25,0])-0.2).clip(min=0)
              best.append((score,stable,p[0],p[2],tu,d,torso,hip,knee,ankle,sp,sr,el,b.copy()))
best=sorted(best,key=lambda x:x[0],reverse=True)[:30]
for row in best:
  print(row[:-1], 'box', row[-1])
PY"
